#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    int fd = open("example.txt", O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }
    char buf[10];
    ssize_t bytes_read = pread(fd, buf, 10, 0);  // Read 10 bytes from offset 0
    if (bytes_read > 0) {
        buf[bytes_read] = '\0';  // Null-terminate the string
        printf("%s\n", buf);  // Print the read content
    }
    close(fd);
    return 0;
}
